import type { Product } from '#shared/types/product'
import { useCart } from '~/composables/useCart'
import { useDiscount } from '~/composables/useDiscount'
import { useNuxtData } from '#app'
import { computed } from 'vue'
import { sumBy } from '#shared/utils/math'
import { applyDiscount } from '~/utils/discount'

/** Cart totals in cents, as shown to the customer. */
export function useCartTotal() {
  const { lines } = useCart()
  const { percent } = useDiscount()
  const { data: products } = useNuxtData<Product[]>('products')
  const subtotal = computed(() => sumBy(lines.value, (line) => {
    const product = products.value?.find(p => p.slug === line.slug)
    return (product?.priceCents ?? 0) * line.qty
  }))
  const total = computed(() => applyDiscount(subtotal.value, percent.value))
  return { subtotal, total, percent }
}

import { formatMoney } from '~/utils/money'

/**
 * Price after discount, as shown in the UI.
 * The discount is rounded down, so the UI never promises more than the server quote.
 */
export function applyDiscount(cents: number, percent: number): number {
  return cents - Math.floor(cents * percent / 100)
}

/** `399` -> `-$3.99`. */
export function formatDiscount(cents: number): string {
  return `-${formatMoney(cents)}`
}

import type { Product } from '#shared/types/product'
import { slugify } from '#shared/utils/slug'

const products: Product[] = [
  ['Notebook', 1999],
  ['Pencil', 150],
  ['Backpack', 4500],
  ['Eraser', 99],
  ['Sticky Notes', 350],
  ['Stapler', 1250],
].map(([name, priceCents]) => ({ slug: slugify(name as string), name: name as string, priceCents: priceCents as number }))

export function listProducts(): Product[] {
  return products
}

export function findProduct(slug: string): Product | undefined {
  return products.find(p => p.slug === slug)
}

